'use strict';
function workbookBorderSettings(){return activeWorkbook.borderTool||=( {preset:'bottom',color:'#000000',lineStyle:'thin'} );}
function workbookBorderIcon(id='all'){
  let path=id==='all'?'M3 3H21V21H3ZM3 12H21M12 3V21':id==='none'?'':id==='top'?'M3 3H21':id==='left'?'M3 3V21':id==='right'?'M21 3V21':id.includes('Outside')||id==='outside'?'M3 3H21V21H3Z':id.startsWith('top')?'M3 3H21M3 21H21':'M3 21H21';
  if(id==='topThickBottom')path='M3 21H21';
  return `<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 3H21V21H3ZM3 12H21M12 3V21" stroke="#87929f" stroke-dasharray="1 2"/><path d="${path}" stroke="currentColor" stroke-width="${/thick/i.test(id)?3:1.5}"/>${id==='topThickBottom'?'<path d="M3 3H21" stroke="currentColor" stroke-width="1.5"/>':''}${/double/i.test(id)?'<path d="M3 18H21" stroke="currentColor"/>':''}</svg>`;
}
function workbookBorderTool(){return `<div class="border-split"><button type="button" data-border-ui="repeat" aria-label="Terapkan border terakhir" title="Bottom Border">${workbookBorderIcon('bottom')}</button><button type="button" data-border-ui="menu" aria-label="Pilihan Borders" aria-haspopup="menu" aria-expanded="false" title="Borders">&#8964;</button></div>`;}
function borderContext(){return {state:activeWorkbook,index:activeWorkbook.sheetIndex,key:activeWorkbook.key,version:activeWorkbook.recordVersion,edits:activeWorkbook.edits,address:workbookRange()};}
function validBorderContext(c){return c&&c.state===activeWorkbook&&c.index===activeWorkbook.sheetIndex&&c.key===activeWorkbook.key&&c.version===activeWorkbook.recordVersion&&c.edits===activeWorkbook.edits&&Boolean(workbookDocument(true))&&!activeWorkbook.saving;}
function closeWorkbookBorders(focus=false){document.getElementById('workbook-border-menu')?.remove();const button=document.querySelector('[data-border-ui=menu]');button?.setAttribute('aria-expanded','false');if(focus)button?.focus({preventScroll:true});}
function applyWorkbookBorder(preset,options={},c=borderContext()){
  if(!validBorderContext(c))return;
  const state=c.state,backup=WorkbookFormat.snapshot(state.book,c.index),undo=[...(state.undo||[])],redo=[...(state.redo||[])];state.historyGroup=null;if(!workbookCheckpoint())return;
  try{WorkbookBorders.apply(state.book,c.index,c.address,preset,{...workbookBorderSettings(),...options});if(preset==='custom'){workbookBorderSettings().preset=preset;workbookBorderSettings().customSides={...options.sides};}else if(WorkbookBorders.presets.some(([id])=>id===preset))workbookBorderSettings().preset=preset;state.historyGroup=null;workbookChanged();restoreWorkbookFocus();}
  catch(error){WorkbookFormat.restore(state.book,backup);state.undo=undo;state.redo=redo;state.historyGroup=null;renderWorkbookSheet();toast(error.message,true);}
}
function borderLineCss(style,color){return `${style==='thick'||style==='double'?3:/medium/i.test(style)?2:1}px ${style==='double'?'double':style==='dotted'?'dotted':/dash/i.test(style)?'dashed':'solid'} ${color}`;}
function syncWorkbookBorderTool(){
  if(!workbookDocument()||!document.getElementById('workbook-grid'))return;const settings=workbookBorderSettings(),button=document.querySelector('[data-border-ui=repeat]');if(button){button.innerHTML=workbookBorderIcon(settings.preset==='custom'?'all':settings.preset);button.title=WorkbookBorders.presets.find(([id])=>id===settings.preset)?.[1]||'Custom Borders';button.setAttribute('aria-pressed',String(Boolean(activeWorkbook.borderMode)));}
  const grid=document.getElementById('workbook-grid');grid.classList.toggle('is-border-drawing',Boolean(activeWorkbook.borderMode));grid.classList.toggle('is-border-erasing',activeWorkbook.borderMode==='erase');
  let badge=document.getElementById('workbook-border-mode');if(!activeWorkbook.borderMode){badge?.remove();return;}if(!badge){badge=document.createElement('div');badge.id='workbook-border-mode';badge.className='border-mode-status';badge.innerHTML='<span role="status"></span><button type="button" data-border-ui="stop" aria-label="Selesai menggambar border" title="Esc">&#215;</button>';document.querySelector('.workbook-bottom-bar').prepend(badge);}badge.querySelector('span').textContent={draw:'Draw Border',grid:'Draw Border Grid',erase:'Erase Border'}[activeWorkbook.borderMode];
}
function showWorkbookBorders(section='main',context=borderContext()){
  if(!validBorderContext(context))return;closeWorkbookBorders();const settings=workbookBorderSettings(),menu=document.createElement('div');menu.id='workbook-border-menu';menu.className='workbook-border-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Borders');
  const item=(action,label,icon='',extra='')=>`<button type="button" role="menuitem" aria-label="${label}" data-border-command="${action}" ${extra}>${icon||'<span class="border-empty-icon"></span>'}<span>${label}</span>${['color','style'].includes(action)?'<span class="border-menu-arrow" aria-hidden="true">&#8250;</span>':''}</button>`;
  if(section==='color')menu.innerHTML=`${item('back','Borders','&#8249;')}<div class="border-color-form"><label for="border-line-color">Warna garis border</label><input id="border-line-color" type="color" value="${settings.color}"><button type="button" data-border-command="use-color">Gunakan Warna</button></div>`;
  else if(section==='style')menu.innerHTML=item('back','Borders','&#8249;')+WorkbookBorders.styles.map(([id,label])=>item('style:'+id,label,`<span class="border-line-swatch" style="border-top:${borderLineCss(id,settings.color)}"></span>`)).join('');
  else menu.innerHTML='<strong class="border-menu-heading">Borders</strong>'+WorkbookBorders.presets.map(([id,label])=>item('preset:'+id,label,workbookBorderIcon(id),['none','outside','bottomDouble','topBottom'].includes(id)?'class="border-menu-separator"':'')).join('')+'<strong class="border-menu-heading border-menu-separator">Draw Borders</strong>'+item('draw','Draw Border',workbookBorderIcon('outside'))+item('grid','Draw Border Grid',workbookBorderIcon('all'))+item('erase','Erase Border',ribbonIcon('clear'))+item('color','Line Color',ribbonIcon('fill'))+item('style','Line Style')+item('custom','More Borders...',workbookBorderIcon('all'),'class="border-menu-separator"');
  document.body.appendChild(menu);const button=document.querySelector('[data-border-ui=menu]'),anchor=button.getBoundingClientRect(),scale=workbookPointerScale(document.querySelector('.workbook-workspace'));menu.style.maxHeight=(innerHeight-16)/scale.y+'px';menu.style.maxWidth=(innerWidth-16)/scale.x+'px';const rect=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(anchor.left,innerWidth-rect.width-8))/scale.x+'px';menu.style.top=Math.max(8,Math.min(anchor.bottom+4,innerHeight-rect.height-8))/scale.y+'px';button.setAttribute('aria-expanded','true');
  menu.onclick=event=>{const target=event.target.closest('[data-border-command]');if(!target||!menu.isConnected)return;const action=target.dataset.borderCommand;if(!validBorderContext(context)){closeWorkbookBorders();return;}
    if(action==='color'||action==='style'||action==='back'){showWorkbookBorders(action==='back'?'main':action,context);return;}
    if(action==='use-color'){settings.color=document.getElementById('border-line-color').value;closeWorkbookBorders(true);return;}
    if(action.startsWith('style:')){settings.lineStyle=action.slice(6);closeWorkbookBorders(true);return;}
    closeWorkbookBorders();if(action.startsWith('preset:'))applyWorkbookBorder(action.slice(7),{},context);else if(action==='custom'){stopWorkbookBorderMode();showWorkbookBorderDialog(context);}else {activeWorkbook.borderMode=action;syncWorkbookBorderTool();restoreWorkbookFocus();}
  };
  menu.onkeydown=event=>{const items=[...menu.querySelectorAll('[role=menuitem]')],at=items.indexOf(document.activeElement);if(event.key==='Escape'){event.preventDefault();closeWorkbookBorders(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();items[event.key==='Home'?0:event.key==='End'?items.length-1:(at+(event.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}else if(event.key==='ArrowLeft'&&section!=='main'){event.preventDefault();showWorkbookBorders('main',context);}};
  menu.querySelector('[role=menuitem]')?.focus({preventScroll:true});
}
function showWorkbookBorderDialog(c){
  if(!validBorderContext(c))return;const settings=workbookBorderSettings(),sides={top:true,bottom:true,left:true,right:true,insideH:false,insideV:false};
  showModal(`${modalHeading('More Borders')}<form id="border-custom-form"><div class="form-grid"><div class="field"><label for="border-custom-style">Line Style</label><select data-native-select id="border-custom-style">${WorkbookBorders.styles.map(([id,label])=>`<option value="${id}" ${id===settings.lineStyle?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="border-custom-color">Line Color</label><input id="border-custom-color" type="color" value="${settings.color}"></div></div><div class="border-custom-presets">${['None','Outline','Inside','All'].map(preset=>`<button type="button" class="btn btn-secondary" data-border-custom-preset="${preset}" aria-label="Preset ${preset}">${preset}</button>`).join('')}</div><div class="border-custom-preview" aria-label="Preview border"><span>Teks</span>${Object.keys(sides).map(side=>`<i data-border-preview="${side}"></i>`).join('')}</div><div class="border-custom-sides">${Object.keys(sides).map(side=>`<button type="button" class="btn btn-secondary" data-border-custom-side="${side}" aria-pressed="${sides[side]}">${{top:'Top',bottom:'Bottom',left:'Left',right:'Right',insideH:'Inside Horizontal',insideV:'Inside Vertical'}[side]}</button>`).join('')}</div><p class="small muted">Berlaku pada ${esc(c.address)}. Sisi yang tidak dipilih akan dihapus.</p><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="close-modal">Batal</button><button type="submit" class="btn btn-primary">Terapkan Borders</button></div></form>`);
  const form=document.getElementById('border-custom-form'),update=()=>{const style=document.getElementById('border-custom-style').value,color=document.getElementById('border-custom-color').value;for(const [side,on] of Object.entries(sides)){form.querySelector(`[data-border-custom-side=${side}]`).setAttribute('aria-pressed',String(on));const node=form.querySelector(`[data-border-preview=${side}]`);node.style.border=0;node.style[side==='left'||side==='right'||side==='insideV'?'borderLeft':'borderTop']=on?borderLineCss(style,color):'1px dotted #c2cad4';}};
  form.onclick=event=>{const toggle=event.target.closest('[data-border-custom-side]'),preset=event.target.closest('[data-border-custom-preset]');if(toggle)sides[toggle.dataset.borderCustomSide]=!sides[toggle.dataset.borderCustomSide];if(preset)for(const side of Object.keys(sides)){const inside=side.startsWith('inside');sides[side]=preset.dataset.borderCustomPreset==='All'||preset.dataset.borderCustomPreset===(inside?'Inside':'Outline');}update();};form.oninput=update;form.onchange=update;
  form.onsubmit=event=>{event.preventDefault();if(!form.isConnected||!modal.open)return;if(!validBorderContext(c)){modal.close();toast('Dokumen berubah. Buka kembali Borders.',true);return;}settings.color=document.getElementById('border-custom-color').value;settings.lineStyle=document.getElementById('border-custom-style').value;modal.close();applyWorkbookBorder('custom',{sides},c);};update();
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-border-ui]');if(!button)return;const action=button.dataset.borderUi;if(action==='stop'){stopWorkbookBorderMode();return;}if(!workbookDocument(true)||activeWorkbook.saving)return;if(action==='menu')document.getElementById('workbook-border-menu')?closeWorkbookBorders():showWorkbookBorders();else if(action==='repeat'){closeWorkbookBorders();const settings=workbookBorderSettings();applyWorkbookBorder(settings.preset,settings.preset==='custom'?{sides:settings.customSides}:{});}});
document.addEventListener('pointerdown',event=>{const menu=document.getElementById('workbook-border-menu');if(menu&&!menu.contains(event.target)&&!event.target.closest('[data-border-ui]'))closeWorkbookBorders();},true);
document.addEventListener('scroll',event=>{const menu=document.getElementById('workbook-border-menu');if(menu&&!menu.contains(event.target)&&event.target!==document.getElementById('main-content'))closeWorkbookBorders();},true);
window.addEventListener('resize',()=>closeWorkbookBorders());window.addEventListener('hashchange',()=>{closeWorkbookBorders();stopWorkbookBorderMode();});window.addEventListener('storage',()=>{closeWorkbookBorders();stopWorkbookBorderMode();});
